 items:[['Thiết bị đúng mẫu đã chọn','cam'],['Lắp chắc, không lung lay, lệch, xước vỡ','cam'],['Thử nước: áp lực, thoát nước, rò rỉ','do'],['Đổ nước thử phễu thu, không đọng','do'],['Thử điện: ổ cắm, công tắc, đèn, quạt, bình nóng lạnh','do'],['Thiết bị điện khu ướt được kiểm tra an toàn, chống rò điện','do'],['Biết vị trí van khóa tổng, van từng khu','cam'],['Giữ phiếu bảo hành, hướng dẫn sử dụng, số điện thoại bảo hành','xanh']],
